+    private TokenLoaderContract.GenerationStore.DeliveryMarker lockAndReadDeliveryMarker() {
+        int locked = em.createNativeQuery("UPDATE auth_delivery SET id = id WHERE id = 1").executeUpdate();
+        if (locked != 1) {
