+
+        ObservedGenerationStore(SqliteTokenState delegate) {
+            this.delegate = delegate;
+        }
+
+        @Override
+        public long lastGeneration() {
+            return delegate.lastGeneration();
+        }
+
+        @Override
+        public void record(long generation) {
